    to the start time (which should be in seconds).  Offset tuples can be
    in any of the forms: (hours), (hours,minutes), or (hours,minutes,seconds).
    """
def sec_from_hms(start: Any, *times: Any) -> object {
    ret = [];
    for t in times {
        cur = 0;
        if (len(t) > 0) {
            cur += t[0] * 3600;
        }
        if (len(t) > 1) {
            cur += t[1] * 60;
        }
        if (len(t) > 2) {
            cur += t[2];
        }
        ret.append((start + cur));
    }
    return ret;
}

