    :param topo_order: Order to arrange nodes
    :return: Ordered nodes (indices)
    """
def ts(nodes: Any, topo_order: Any) -> object {
    node_set = `set(nodes);
    return [
        n
        for n in topo_order
        if (n in node_set)
    ];
